#!/usr/bin/env bash
# The scripted manual engine smoke (ADR 1.10.26ac D10, AC15), on a machine
# with Unreal Engine installed. Never run by public CI: a hosted runner
# cannot hold the engine. Four stages, stopping at the first failure:
#
#   0  clang-tidy (the harness's .clang-tidy) over the Runtime module's
#      compile database, generated by UBT
#   1  RunUAT BuildPlugin for this host's platforms, failing on any warning
#      from the plugin's own sources (Win64, Linux, Android from Windows;
#      Mac and IOS from macOS)
#   2  the automation specs headless; a failed or skipped spec fails
#   3  unreal/smoke/ built with the plugin and the snippet, and the sample
#      packaged for the play-through on this host and its devices
#
#   smoke.sh [--dry-run] <UE_ROOT> 5.<m>
#
# Run it once on the oldest supported version (unreal/engine-versions.txt's
# first line) before the first release that ships the plugin, and once per
# supported version before each Fab submission. Record the engine version,
# host, devices and each stage's log tail in the ADR's As built.
set -euo pipefail

dry=0
if [ "${1:-}" = --dry-run ]; then dry=1; shift; fi
ue_root=${1:?usage: smoke.sh [--dry-run] <UE_ROOT> 5.<m>}
ue=${2:?usage: smoke.sh [--dry-run] <UE_ROOT> 5.<m>}
here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../.." && pwd)
scratch=${SMOKE_DIR:-$root/target/unreal-smoke/UE$ue}
logs=$scratch/logs
project=$scratch/LingaraSmoke/LingaraSmoke.uproject

case "$(uname -s)" in
  Darwin) host=Mac; platforms=Mac+IOS; editor=$ue_root/Engine/Binaries/Mac/UnrealEditor-Cmd ;;
  MINGW* | MSYS* | CYGWIN*) host=Win64; platforms=Win64+Linux+Android; editor=$ue_root/Engine/Binaries/Win64/UnrealEditor-Cmd.exe ;;
  *) host=Linux; platforms=Linux; editor=$ue_root/Engine/Binaries/Linux/UnrealEditor-Cmd ;;
esac
uat=$ue_root/Engine/Build/BatchFiles/RunUAT.$([ "$host" = Win64 ] && echo bat || echo sh)
ubt=$ue_root/Engine/Build/BatchFiles/$([ "$host" = Win64 ] && echo Build.bat || echo "$host/Build.sh")

run() {
  echo "+ $*"
  [ "$dry" -eq 1 ] || "$@"
}

stage() { echo; echo "── stage $1: $2"; }

# A stage's output, kept in logs/ for As built (a dry run keeps nothing).
keep() {
  if [ "$dry" -eq 1 ]; then cat; else tee "$1"; fi
}

# A scratch copy of unreal/smoke/ holding the plugin and the snippet's two
# files, so the snippet compiles in every smoke (D8).
prepare() {
  run rm -rf "$scratch"
  run mkdir -p "$logs" "$scratch/LingaraSmoke/Plugins" "$scratch/LingaraSmoke/Source/LingaraSmoke"
  run cp -R "$root/unreal/smoke/." "$scratch/LingaraSmoke/"
  run cp -R "$root/unreal/LingaraEmbed" "$scratch/LingaraSmoke/Plugins/"
  run cp "$root/snippets/player/unreal/LingaraEmbedSnippet.cpp" "$root/snippets/player/unreal/LingaraEmbedSnippetActor.h" \
    "$scratch/LingaraSmoke/Source/LingaraSmoke/"
}

stage0_tidy() {
  stage 0 "clang-tidy over the Runtime module"
  run "$ubt" LingaraSmokeEditor "$host" Development "-Project=$project" -mode=GenerateClangDatabase "-OutputDir=$scratch"
  run clang-tidy --quiet -p "$scratch" --config-file="$root/unreal/harness/.clang-tidy" \
    "$scratch"/LingaraSmoke/Plugins/LingaraEmbed/Source/LingaraEmbed/Private/*.cpp
}

stage1_build_plugin() {
  stage 1 "BuildPlugin for $platforms"
  run "$uat" BuildPlugin "-Plugin=$scratch/LingaraSmoke/Plugins/LingaraEmbed/LingaraEmbed.uplugin" \
    "-Package=$scratch/BuiltPlugin" "-TargetPlatforms=$platforms" -Rocket 2>&1 | keep "$logs/build-plugin.log"
  if [ "$dry" -eq 0 ] && grep -E 'LingaraEmbed[/\\]Source.*: warning' "$logs/build-plugin.log"; then
    echo "✗ the plugin's own sources warn"
    exit 1
  fi
}

stage2_specs() {
  stage 2 "automation specs, headless"
  run "$editor" "$project" -ExecCmds="Automation RunTests LingaraEmbed; Quit" -unattended -nullrhi -nosound \
    -nosplash -log -ReportExportPath="$logs/specs" 2>&1 | keep "$logs/specs.log"
  if [ "$dry" -eq 0 ] && ! jq -e '.failed == 0 and .notRun == 0 and .succeeded > 0' "$logs/specs/index.json" > /dev/null; then
    echo "✗ a spec failed or was skipped: $logs/specs/index.json"
    exit 1
  fi
}

stage3_package() {
  stage 3 "the sample, packaged for the play-through"
  run "$uat" BuildCookRun "-project=$project" "-platform=$host" -clientconfig=Development -build -cook -stage -pak \
    -package -archive "-archivedirectory=$scratch/Packaged" 2>&1 | keep "$logs/package.log"
  echo "Play-through (by hand, AC15): run tools/demo-token-server with a metered client's credentials;"
  echo "  Android: adb reverse tcp:8787 tcp:8787"
  echo "  iOS:     socat TCP-LISTEN:8788,fork,bind=<lan-ip> TCP:127.0.0.1:8787, and type http://<lan-ip>:8788/token"
  echo "  Then a token fetch, a streamed NPC reply at two levels and one practice item, on each device."
}

prepare
stage0_tidy
stage1_build_plugin
stage2_specs
stage3_package
echo
echo "✓ smoke stages 0–3 ran for UE $ue on $host$([ "$dry" -eq 1 ] && echo ' (dry run: nothing executed)')"
